<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\Accounting\AccountingContext;use App\Services\Accounting\AccountingEngine;use App\Services\InventoryLotService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class InventoryController extends Controller
{
 public function index(Request $r,AccountingContext $c,InventoryLotService $lots){return response()->json(['status'=>true,'unit'=>\App\Services\Uom\InventoryQuantitySql::available()?'PER_ROW':'KG','data'=>$lots->summary($c->companyId($r),$c->branchFilter($r))]);}
 public function lots(Request $r,AccountingContext $c,InventoryLotService $lots){return response()->json(['status'=>true,'unit'=>\App\Services\Uom\InventoryQuantitySql::available()?'PER_ROW':'KG','data'=>$lots->lots($c->companyId($r),$c->branchFilter($r),$r->filled('item_id')?(int)$r->item_id:null)]);}
 public function movements(Request $r,AccountingContext $c){$q=DB::table('inventory_lot_movements as m')->join('inventory_lots as l','l.id','=','m.inventory_lot_id')->join('items as i','i.id','=','m.item_id')->leftJoin('branches as b','b.id','=','m.branch_id')->where('m.company_id',$c->companyId($r));$bid=$c->branchFilter($r);if($bid!==null)$q->where('m.branch_id',$bid);if($r->filled('item_id'))$q->where('m.item_id',(int)$r->item_id);if($r->filled('from_date'))$q->whereDate('m.movement_at','>=',$r->from_date);if($r->filled('to_date'))$q->whereDate('m.movement_at','<=',$r->to_date);return response()->json(['status'=>true,'unit'=>\App\Services\Uom\InventoryQuantitySql::available()?'PER_ROW':'KG','data'=>$q->select('m.*','l.lot_number','i.item_code','i.item_name','i.base_unit_code','b.branch_name')->orderByDesc('m.movement_at')->limit(1000)->get()]);}
 public function valuation(Request $r,AccountingContext $c){
  $quantity=\App\Services\Uom\InventoryQuantitySql::lot('inventory_lots');
  $q=DB::table('inventory_lots')->where('inventory_lots.company_id',$c->companyId($r))->whereRaw("($quantity)>0");$bid=$c->branchFilter($r);if($bid!==null)$q->where('inventory_lots.branch_id',$bid);
  $x=(clone $q)->selectRaw('COALESCE(SUM(qty_remaining_kg),0) balance_kg, COALESCE(SUM('.\App\Services\InventoryLotValue::sqlValue('inventory_lots').'),0) stock_value, COUNT(*) open_lots')->first();
  $groups=(clone $q)->join('items as i','i.id','=','inventory_lots.item_id')->select('i.base_unit_code')->selectRaw("SUM($quantity) base_quantity")->groupBy('i.base_unit_code')->get();
  $kg=round((float)($x->balance_kg??0),3);return response()->json(['status'=>true,'data'=>['balance_kg'=>$kg,'balance_ton'=>round($kg/1000,3),'stock_value'=>round((float)($x->stock_value??0),3),'open_lots'=>(int)($x->open_lots??0),'quantities_by_unit'=>$groups]]);
 }
 public function adjustment(Request $r,AccountingContext $c,AccountingEngine $a,InventoryLotService $lots){$v=$r->validate(['branch_id'=>'nullable|integer','item_id'=>'required|integer','movement_type'=>'required|in:IN,OUT','qty_kg'=>'required_without:quantity|numeric|gt:0','quantity'=>'required_without:qty_kg|string|regex:/^\d+(?:\.\d{1,6})?$/D','unit_code'=>'nullable|string|max:20','total_cost'=>'nullable|string|regex:/^\d+(?:\.\d{1,3})?$/D','request_key'=>'nullable|string|max:80','unit_cost_per_ton'=>'nullable|numeric|min:0','movement_date'=>'nullable|date','notes'=>'required|string|min:3']);try{$cid=$c->companyId($r);$bid=$c->branchForOperation($r);$item=DB::table('items')->where('company_id',$cid)->where('id',$v['item_id'])->where('is_active',1)->first();if(!$item)throw new \RuntimeException('الصنف غير صالح.');if(($item->inventory_quantity_version??'LEGACY_KG')==='BASE_V1')return response()->json(['status'=>true,'data'=>app(\App\Services\Uom\BaseAdjustmentService::class)->post($cid,$bid,(int)$c->userId($r),$v)]);return DB::transaction(function()use($r,$c,$a,$lots,$cid,$bid,$v){$kg=round((float)$v['qty_kg'],3);$date=$v['movement_date']??now();if($v['movement_type']==='IN'){$perTon=round((float)($v['unit_cost_per_ton']??0),3);if($perTon<=0)throw new \RuntimeException('أدخل تكلفة الطن للتسوية الموجبة.');$total=round(($kg/1000)*$perTon,3);$lot=$lots->createInboundLot(['company_id'=>$cid,'branch_id'=>$bid,'item_id'=>$v['item_id'],'qty_kg'=>$kg,'base_cost'=>$total,'source_type'=>'ADJUSTMENT','received_at'=>$date,'notes'=>$v['notes'],'created_by'=>$c->userId($r)]);$unitKg=round($perTon/1000,6);}else{$con=$lots->consumeFifo($cid,$bid,(int)$v['item_id'],$kg,'ADJUSTMENT',0,null,$c->userId($r));$total=$con['total_cost'];$unitKg=$con['unit_cost_per_kg'];$perTon=round($unitKg*1000,3);$lot=null;}$id=DB::table('stock_movements')->insertGetId(['company_id'=>$cid,'branch_id'=>$bid,'item_id'=>$v['item_id'],'inventory_lot_id'=>$lot,'movement_type'=>$v['movement_type'],'source_type'=>'ADJUSTMENT','source_id'=>null,'movement_date'=>$date,'qty'=>round($kg/1000,3),'qty_kg'=>$kg,'unit_cost'=>$perTon,'unit_cost_per_kg'=>$unitKg,'total_cost'=>$total,'notes'=>$v['notes'],'created_by'=>$c->userId($r),'created_at'=>now(),'updated_at'=>now()]);DB::table('stock_movements')->where('id',$id)->update(['source_id'=>$id]);$res=$a->inventory(['company_id'=>$cid,'movement_id'=>$id,'created_by'=>$c->userId($r)]);if(!$res->success)throw new \RuntimeException($res->message);return response()->json(['status'=>true,'message'=>'تمت تسوية المخزون وترحيلها محاسبيًا.','movement_id'=>$id,'journal_entry_id'=>$res->journalEntryId]);});}catch(\Throwable $e){return response()->json(['status'=>false,'message'=>\App\Support\ApiExceptionMessage::for($e)],422);}}
 public function voidAdjustment(Request $r,int $id,AccountingContext $c){$v=$r->validate(['reason'=>'required|string|min:5|max:2000']);try{$head=DB::table('uom_inventory_adjustments')->where('company_id',$c->companyId($r))->where('id',$id)->first();if(!$head)return response()->json(['status'=>false,'message'=>'المستند غير موجود.'],404);$branch=$c->branchForOperation($r,(int)$head->branch_id);return response()->json(['status'=>true,'data'=>app(\App\Services\Uom\BaseAdjustmentService::class)->void($c->companyId($r),$branch,$id,(int)$c->userId($r),$v['reason'])]);}catch(\Throwable $e){return response()->json(['status'=>false,'message'=>\App\Support\ApiExceptionMessage::for($e)],422);}}
}
